insert into public.lessons (id, unit_id, position, title, description, tip, xp_reward, published) values ('en-beginner-u6-l4', 'en-beginner-u6', 4, 'Questions with Do & Does', 'Ask yes/no questions in the present simple.', 'Questions: Do + I/you/we/they + verb? Does + he/she/it + verb? After ''does'', the verb has no -s: Does she like tea? (not ''Does she likes'').', 21, true) on conflict (id) do update set title = excluded.title, description = excluded.description, tip = excluded.tip, xp_reward = excluded.xp_reward;
